def render(code,values):
 pattern=r'\b(?:'+'|'.join(re.escape(k) for k in values)+r')\b';code=re.sub(pattern,lambda m:repr(values[m[0]]),code);ast.parse(code);return code

def invoke(node,code,archive):
 pod,host=base.NODES[node];mapped=base.invoke(['kubectl get pod -n default '+shlex.quote(pod)+" -o jsonpath='{.status.hostIP}'"],timeout=30);assert mapped['rc']==0 and mapped['stdout']==f'172.16.12.{node}'
 expected=json.loads((ROOT/'config/diagnostic-runs-v1/sglang-C16-D-profile.json').read_text())['runtime_containers'][str(node)]
